use std::fs

fn find(names: Vec<string>, n: string) -> int {
    let mut i: int = 0
    while i < names.len() as int {
        if names[i as usize] == n {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = Vec::new()
    let mut bals: Vec<int> = Vec::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "open" && parts.len() >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if find(names, parts[1]) >= 0 {
                println("error: duplicate account")
            } else {
                names.push(parts[1])
                bals.push(amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && parts.len() >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            let i = find(names, parts[1])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else if cmd == "deposit" {
                bals[i as usize] = bals[i as usize] + amt
                println("ok")
            } else if bals[i as usize] < amt {
                println("error: insufficient funds")
            } else {
                bals[i as usize] = bals[i as usize] - amt
                println("ok")
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            let i = find(names, parts[1])
            let j = find(names, parts[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else if j < 0 {
                println("error: unknown account ${parts[2]}")
            } else if i == j {
                println("error: same account")
            } else if bals[i as usize] < amt {
                println("error: insufficient funds")
            } else {
                bals[i as usize] = bals[i as usize] - amt
                bals[j as usize] = bals[j as usize] + amt
                println("ok")
            }
        } else if cmd == "balance" && parts.len() >= 2 {
            let i = find(names, parts[1])
            if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else {
                println("${bals[i as usize]}")
            }
        }
    }
    let mut order: Vec<string> = Vec::new()
    for n in names {
        order.push(n)
    }
    order.sort()
    for n in order {
        let i = find(names, n)
        println("${n} ${bals[i as usize]}")
    }
}

